  tenant_id uuid not null references aip.tenants(id) on delete cascade,
  row_key text not null,
  "rule_id" varchar(200),
  "rule_name" varchar(200),
  "rule_type" varchar(200),
  "rule_value" varchar(200),
  "unit" varchar(200),
  "governance_status" varchar(200),
