  using (aip.has_role(tenant_id, array['planner','admin'])) with check (aip.has_role(tenant_id, array['planner','admin']));
drop trigger if exists t_audit on aip."pno_scheduling_rules";
create trigger t_audit after insert or update or delete on aip."pno_scheduling_rules" for each row execute function aip.audit_row();
drop trigger if exists t_touch on aip."pno_scheduling_rules";
create trigger t_touch before update on aip."pno_scheduling_rules" for each row execute function aip.touch_updated_at();

